3. 
   pid_t pid[N]; 
4. 
   int i, child_status; 
5. 
   for (i = 0; i < N; i++) { 

6. 
        if ((pid[i] = fork()) == 0) { 
7. 
            exit(100+i); /* Child */ 
8. 
        } 
9. 
    } 
10.     printf("hello!\n"); 
11.     for (i = 0; i < N; i++) { /* Parent */ 
12.         pid_t wpid = wait(&child_status); 
13.         if (WIFEXITED(child_status)) 
14.             printf("Child %d terminated with exit status %d\n", 
15.                    wpid, WEXITSTATUS(child_status)); 
